<template><el-dialog :model-value="modelValue" title="数字人预览" width="520" @update:model-value="$emit('update:modelValue',$event)"><div class="stage" :data-state="state"><img v-if="config?.avatarUrl" :src="config.avatarUrl" class="avatar"/><div v-else class="avatar fallback">Digital Human</div><div class="state">{{state}}</div><div class="subtitle">{{subtitle||config?.welcomeText}}</div></div><div class="controls"><el-button v-for="s in states" :key="s" @click="setState(s)">{{s}}</el-button></div></el-dialog></template>
<script setup lang="ts">import{ref,watch}from'vue';import type{DigitalHumanPreviewVO,DigitalHumanState}from'@/api/ai/digital-human';import{Static2DRenderer}from'../runtime/DigitalHumanRenderer';const props=defineProps<{modelValue:boolean;config?:DigitalHumanPreviewVO}>();defineEmits(['update:modelValue']);const states:DigitalHumanState[]=['IDLE','LISTENING','THINKING','SPEAKING','EXECUTING','ERROR'];const state=ref<DigitalHumanState>('IDLE'),subtitle=ref('');const renderer=new Static2DRenderer();watch(()=>props.config,c=>{if(c)renderer.load(c)},{immediate:true});function setState(s:DigitalHumanState){renderer.setState(s);state.value=s}</script>
<style scoped>.stage{min-height:320px;display:flex;flex-direction:column;align-items:center;justify-content:center;gap:12px}.avatar{max-height:240px;max-width:100%;transition:transform .15s}.stage[data-state=SPEAKING] .avatar{transform:scale(1.02)}.fallback{display:flex;align-items:center;justify-content:center;width:220px;height:240px;background:var(--el-fill-color-light)}.state{font-weight:600}.subtitle{min-height:24px}.controls{display:flex;flex-wrap:wrap;gap:6px}</style>